B.CU=new A.dU("Nox Check","Nox Check","Nox Check")
B.bqk=new A.dU("Nox couldn\u2019t read any words here. Paste the message text instead.","Nox \u0915\u094b \u092f\u0939\u093e\u0902 \u0915\u094b\u0908 \u0936\u092c\u094d\u0926 \u0928\u0939\u0940\u0902 \u092e\u093f\u0932\u0947\u0964 \u092e\u0948\u0938\u0947\u091c \u0915\u093e \u091f\u0947\u0915\u094d\u0938\u094d\u091f \u092a\u0947\u0938\u094d\u091f \u0915\u0930\u0947\u0902\u0964","Nox \u0932\u093e \u0907\u0925\u0947 \u0915\u094b\u0923\u0924\u0947\u0939\u0940 \u0936\u092c\u094d\u0926 \u0938\u093e\u092a\u0921\u0932\u0947 \u0928\u093e\u0939\u0940\u0924. \u092e\u0947\u0938\u0947\u091c\u091a\u093e \u092e\u091c\u0915\u0942\u0930 \u092a\u0947\u0938\u094d\u091f \u0915\u0930\u093e.")
B.bql=new A.dU("NO SUS is independent. Not affiliated with the Government of India.","NO SUS \u090f\u0915 \u0938\u094d\u0935\u0924\u0902\u0924\u094d\u0930 \u0910\u092a \u0939\u0948\u0964 \u092d\u093e\u0930\u0924 \u0938\u0930\u0915\u093e\u0930 \u0938\u0947 \u0938\u0902\u092c\u0926\u094d\u0927 \u0928\u0939\u0940\u0902\u0964","NO SUS \u0938\u094d\u0935\u0924\u0902\u0924\u094d\u0930 \u0972\u092a \u0906\u0939\u0947. \u092d\u093e\u0930\u0924 \u0938\u0930\u0915\u093e\u0930\u0936\u0940 \u0938\u0902\u0932\u0917\u094d\u0928 \u0928\u093e\u0939\u0940.")
B.XO=new A.dU("Make a SUS card","SUS \u0915\u093e\u0930\u094d\u0921 \u092c\u0928\u093e\u090f\u0902","SUS \u0915\u093e\u0930\u094d\u0921 \u092c\u0928\u0935\u093e")
B.bqm=new A.dU("Share the card","\u0915\u093e\u0930\u094d\u0921 \u0936\u0947\u092f\u0930 \u0915\u0930\u0947\u0902","\u0915\u093e\u0930\u094d\u0921 \u0936\u0947\u0905\u0930 \u0915\u0930\u093e")
